module.exports = "';\nconst _STATS_B64 = ''+'Ni4zLCAic29saWRlIl0sIFsiTGEgVmVybmF6IiwgNzQyMDAsIDE4LCAyOTU2LCAzMTUxLCAtMjguNCwgMy4zLCAibW95ZW5uZSJdXQ==';\nconst _KPIS_B64 = '';\nfunction _b64json(s){ return JSON.parse(decodeURIComponent(escape(atob(s)))); }\nconst LEADS = _b64json(_LEADS_B64);\nconst STATS = _b64json(_STATS_B64);\nconst KPIS = _b64json(_KPIS_B64);\n\nconst COLS = ['adresse','commune','secteur','prioridade','score','tipo','superficie','pieces',\n              'dpe','passoire','ano','terreno','prixm2','valor','maisvalia','duree',\n              'argDpe','argTerreno','argPrudent','nbComp','echeanceDpe','gmaps','motivos','comparaveis'];\nconst IDX = Object.fromEntries(COLS.map((c,i)=>[c,i]));\n\nconst fmtEUR = new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0});\nconst fmtNum = new Intl.NumberFormat('fr-FR');\nconst fmtPct = (v)=> (v>0?'+':'') + v.toFixed(1).replace('.',',') + ' %';\nconst fmtCompactEUR = (v)=> v>=1e6 ? (v/1e6).toFixed(1).replace('.',',') + ' M \u20ac' : fmtEUR.format(v);\n\nconst state = { search:'', priority:'ALL', commune:'', passoireOnly:false, terrenoOnly:false,\n                sortKey: IDX.score, sortDir:-1, page:1, pageSize:40 };\n\nfunction dpeClass(d){\n  if(!d) return 'mid';\n  if(['A','B'].includes(d)) return 'good';\n  if(['E','F','G'].includes(d)) return 'bad';\n  return 'mid';\n}\n\nfunction buildKpis(){\n  const el = document.getElementById('kpiRow');\n  const tiles = [\n    {label:'Adresses prioritaires', value: fmtNum.format(KPIS.total), sub:'score \u2265 50'},\n    {label:'Priorit\u00e9 maximale', value: fmtNum.format(KPIS.prioridade_a), sub:'score \u2265 70', gold:true},\n    {label:'Score moyen', value: KPIS.score_medio.toFixed(1).replace('.',','), sub:'sur 100'},\n    {label:'Passoires thermiques', value: fmtNum.format(KPIS.passoires), sub:'DPE E \u00b7 F \u00b7 G'},\n    {label:'Terrain \u2265 1000 m\u00b2', value: fmtNum.format(KPIS.com_terreno_grande), sub:'potentiel de division'},\n    {label:'Valeur du portefeuille', value: fmtCompactEUR(KPIS.valor_total_estimado), sub:'estimation agr\u00e9g\u00e9e'},\n  ];\n  el.innerHTML = tiles.map(t=>`\n    <div class=\"kpi\">\n      <div class=\"kpi-label\">${t.label}</div>\n      <div class=\"kpi-value${t.gold?' gold':''}\">${t.value}</div>\n      <div class=\"kpi-sub\">${t.sub}</div>\n    </div>`).join('');\n}\n\nfunction buildCommuneSelect(){\n  const sel = document.getElementById('communeSelect');\n  const names = [...new Set(STATS.map(s=>s[0]))].sort((a,b)=>a.localeCompare(b,'fr'));\n  names.forEach(n=>{\n    const o = document.createElement('option');\n    o.value = n; o.textContent = n;\n    sel.appendChild(o);\n  });\n}\n\nfunction buildCommunePanel(){\n  const list = document.getElementById('communeList');\n  const rows = [...STATS].sort((a,b)=> (b[4]||0) - (a[4]||0));\n  const max = Math.max(...rows.map(r=>r[4]||0));\n  list.innerHTML = rows.map(r=>{\n    const [commune,, nbVentes, prixBrut, prixActualise, evo, tauxAnnuel] = r;\n    const pct = max ? Math.round((prixActualise||0)/max*100) : 0;\n    const upFlag = (tauxAnnuel||0) >= 0;\n    return `<div class=\"commune-row\" data-commune=\"${commune}\">\n      <span class=\"commune-name\">${commune}</span>\n      <span class=\"commune-val\">${fmtNum.format(prixActualise||0)} \u20ac</span>\n      <div class=\"commune-bar-track\"><div class=\"commune-bar-fill\" style=\"width:${pct}%\"></div></div>\n      <div class=\"commune-meta\">\n        <span>${fmtNum.format(nbVentes||0)} ventes \u00b7 brut ${fmtNum.format(prixBrut||0)} \u20ac</span>\n        <span class=\"evo ${upFlag?'up':'down'}\">${upFlag?'\u25b2':'\u25bc'} ${Math.abs(tauxAnnuel||0).toFixed(1)}%/an</span>\n      </div>\n    </div>`;\n  }).join('');\n  list.querySelectorAll('.commune-row').forEach(row=>{\n    row.addEventListener('click', ()=>{\n      const c = row.dataset.commune;\n      state.commune = (state.commune === c) ? '' : c;\n      document.getElementById('communeSelect').value = state.commune;\n      state.page = 1;\n      render();\n    });\n  });\n}\n\nfunction filtered(){\n  let rows = LEADS;\n  if(state.priority !== 'ALL') rows = rows.filter(r=>r[IDX.prioridade]===state.priority);\n  if(state.commune) rows = rows.filter(r=>r[IDX.commune]===state.commune);\n  if(state.passoireOnly) rows = rows.filter(r=>r[IDX.passoire]===true);\n  if(state.terrenoOnly) rows = rows.filter(r=>(r[IDX.terreno]||0) >= 1000);\n  if(state.search){\n    const q = state.search.toLowerCase();\n    rows = rows.filter(r=> (r[IDX.adresse]||'').toLowerCase().includes(q) || (r[IDX.commune]||'').toLowerCase().includes(q));\n  }\n  const key = state.sortKey, dir = state.sortDir;\n  rows = [...rows].sort((a,b)=>{\n    const av = a[key], bv = b[key];\n    if(av==null && bv==null) return 0;\n    if(av==null) return 1;\n    if(bv==null) return -1;\n    if(typeof av === 'string') return dir * av.localeCompare(bv,'fr');\n    return dir * (av - bv);\n  });\n  return rows;\n}\n\nfunction rowDetail(r, idx){\n  const blocks = [];\n  if(r[IDX.argDpe]) blocks.push({h:'Argument \u2014 passoire thermique', p:r[IDX.argDpe]});\n  if(r[IDX.argTerreno]) blocks.push({h:'Argument \u2014 terrain', p:r[IDX.argTerreno]});\n  if(r[IDX.argPrudent]) blocks.push({h:'Argument \u2014 tendance de march\u00e9', p:r[IDX.argPrudent]});\n  blocks.push({h:'Motifs du score', p:r[IDX.motivos] || '\u2014'});\n  if(r[IDX.comparaveis]) blocks.push({h:'Ventes comparables (prix r\u00e9el de l\\'ann\u00e9e)', p:r[IDX.comparaveis]});\n  const compTxt = r[IDX.nbComp] ? `${r[IDX.nbComp]} vente(s) comparable(s) dans la rue/commune` : 'Aucun comparable direct dans cette rue';\n  return `<div class=\"detail-grid\">\n    ${blocks.map(b=>`<div class=\"detail-block\"><h4>${b.h}</h4><p class=\"argument-quote\">${b.p}</p></div>`).join('')}\n    <div class=\"detail-block\"><h4>Base d'estimation</h4><p>${compTxt}. Ann\u00e9e de construction : ${r[IDX.ano]||'inconnue'}. Anciennet\u00e9 de d\u00e9tention : ${r[IDX.duree]!=null? r[IDX.duree]+' ans' : 'jamais vendu sur la fen\u00eatre DVF'}. Prix au m\u00b2 actualis\u00e9 \u00e0 2025.</p></div>\n  </div>\n  <div class=\"cta-row\">\n    ${r[IDX.gmaps] ? `<a class=\"cta\" href=\"${r[IDX.gmaps]}\" target=\"_blank\" rel=\"noopener\">Voir sur la carte \u2197</a>` : ''}\n  </div>`;\n}\n\nfunction render(){\n  const rows = filtered();\n  const total = rows.length;\n  const pages = Math.max(1, Math.ceil(total/state.pageSize));\n  state.page = Math.min(state.page, pages);\n  const start = (state.page-1)*state.pageSize;\n  const pageRows = rows.slice(start, start+state.pageSize);\n\n  const tbody = document.getElementById('tbody');\n  if(pageRows.length === 0){\n    tbody.innerHTML = `<tr><td colspan=\"8\" class=\"empty-state\">Aucune adresse ne correspond \u00e0 ces filtres.</td></tr>`;\n  } else {\n    tbody.innerHTML = pageRows.map((r,i)=>{\n      const gi = start+i;\n      const dc = dpeClass(r[IDX.dpe]);\n      const priorityCls = r[IDX.prioridade]==='A' ? 'pA' : 'pB';\n      const priorityLbl = r[IDX.prioridade]==='A' ? 'A \u00b7 maximale' : 'B \u00b7 \u00e9lev\u00e9e';\n      const mv = r[IDX.maisvalia];\n      return `<tr class=\"row\" data-idx=\"${gi}\">\n        <td><span class=\"chev\">\u25b8</span><span class=\"pill ${priorityCls}\">${priorityLbl}</span><br>\n            <span class=\"addr\">${r[IDX.adresse]||'\u2014'}</span><span class=\"addr-sub\">${r[IDX.commune]||''} \u00b7 ${r[IDX.secteur]||''}</span></td>\n        <td class=\"num\">${r[IDX.score]!=null?r[IDX.score]:'\u2014'}</td>\n        <td>${r[IDX.tipo]||'\u2014'}</td>\n        <td class=\"num\">${r[IDX.superficie]!=null?Math.round(r[IDX.superficie])+' m\u00b2':'\u2014'}</td>\n        <td><div class=\"dpe-wrap\"><span class=\"badge-dpe ${dc}\">${r[IDX.dpe]||'?'}</span>${r[IDX.echeanceDpe]?`<span class=\"dpe-echeance\">interdit ${r[IDX.echeanceDpe]}</span>`:''}</div></td>\n        <td class=\"num\">${r[IDX.terreno]!=null?Math.round(r[IDX.terreno])+' m\u00b2':'\u2014'}</td>\n        <td class=\"num\">${r[IDX.valor]!=null?fmtEUR.format(r[IDX.valor]):'\u2014'}</td>\n        <td class=\"num\">${mv!=null?fmtPct(mv):'\u2014'}</td>\n      </tr>\n      <tr class=\"detail\" data-detail-for=\"${gi}\"><td colspan=\"8\">${rowDetail(r,gi)}</td></tr>`;\n    }).join('');\n\n    tbody.querySelectorAll('tr.row').forEach(tr=>{\n      tr.addEventListener('click', (e)=>{\n        if(e.target.closest('a')) return;\n        const idx = tr.dataset.idx;\n        const det = tbody.querySelector(`tr.detail[data-detail-for=\"${idx}\"]`);\n        tr.classList.toggle('open');\n        det.classList.toggle('open');\n      });\n    });\n  }\n\n  document.getElementById('countBadge').innerHTML = `<b>${fmtNum.format(total)}</b> sur ${fmtNum.format(LEADS.length)} adresses`;\n  document.getElementById('pageLabel').textContent = `Page ${state.page} sur ${pages}`;\n  document.getElementById('prevPage').disabled = state.page<=1;\n  document.getElementById('nextPage').disabled = state.page>=pages;\n\n  document.querySelectorAll('.commune-row').forEach(row=>{\n    row.classList.toggle('active', row.dataset.commune === state.commune);\n  });\n}\n\nfunction init(){\n  buildKpis();\n  buildCommuneSelect();\n  buildCommunePanel();\n\n  document.getElementById('searchInput').addEventListener('input', (e)=>{\n    state.search = e.target.value.trim();\n    state.page = 1;\n    render();\n  });\n  document.querySelectorAll('#prioritySeg button').forEach(btn=>{\n    btn.addEventListener('click', ()=>{\n      document.querySelectorAll('#prioritySeg button').forEach(b=>b.classList.remove('active'));\n      btn.classList.add('active');\n      state.priority = btn.dataset.val;\n      state.page = 1;\n      render();\n    });\n  });\n  document.getElementById('communeSelect').addEventListener('change', (e)=>{\n    state.commune = e.target.value;\n    state.page = 1;\n    render();\n  });\n  document.getElementById('passoireToggle').addEventListener('change', (e)=>{\n    state.passoireOnly = e.target.checked;\n    state.page = 1;\n    render();\n  });\n  document.getElementById('terrenoToggle').addEventListener('change', (e)=>{\n    state.terrenoOnly = e.target.checked;\n    state.page = 1;\n    render();\n  });\n  document.querySelectorAll('#leadsTable thead th[data-key]').forEach(th=>{\n    th.addEventListener('click', ()=>{\n      const key = parseInt(th.dataset.key,10);\n      if(state.sortKey === key) state.sortDir *= -1;\n      else { state.sortKey = key; state.sortDir = -1; }\n      document.querySelectorAll('#leadsTable thead th').forEach(h=>h.classList.remove('sorted'));\n      th.classList.add('sorted');\n      th.querySelector('.arrow').textContent = state.sortDir===-1 ? '\u25bc' : '\u25b2';\n      render();\n    });\n  });\n  document.getElementById('prevPage').addEventListener('click', ()=>{ state.page--; render(); });\n  document.getElementById('nextPage').addEventListener('click', ()=>{ state.page++; render(); });\n\n  render();\n}\n\ninit();\n\n</script>\n\n\n\n</body></html>";
